const $ = id => document.getElementById(id);
function openBooking() { $('welcome').hidden = true; $('booking').hidden = false; $('booking').scrollIntoView?.({behavior:'smooth',block:'start'}); }
function validDate(value) { if(!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false; const date = new Date(value+'T12:00:00Z'); return !Number.isNaN(date.valueOf()) && date.toISOString().slice(0,10) === value; }
$('hero-go').addEventListener('click', openBooking);
$('nav-go').addEventListener('click', () => { $('prices').hidden = false; });
$('cookie-close').addEventListener('click', () => { $('cookies').hidden = true; });
let selectedTime = ''; let waiverAccepted = false;
document.querySelectorAll('[data-time]').forEach(slot => slot.addEventListener('click', () => { selectedTime = slot.dataset.time; document.querySelectorAll('[data-time]').forEach(other => other.classList.toggle('selected', other === slot)); }));
$('waiver').addEventListener('click', () => { waiverAccepted = !waiverAccepted; $('waiver').classList.toggle('selected',waiverAccepted); });
let toastTimer;
$('booking-form').addEventListener('submit', event => {
  event.preventDefault();
  const name = $('name').value.trim(); const email = $('email').value.trim(); const date = $('date').value;
  if(!name || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || !validDate(date) || !selectedTime || !waiverAccepted) { $('error').textContent = 'Invalid input'; return; }
  $('error').textContent = ''; $('toast').hidden = false;
  clearTimeout(toastTimer); toastTimer = setTimeout(() => { $('toast').hidden = true; }, 2500);
});
